function [fr] = bearing_friction(om, coulomb, viscous, fscale)
%BEARING_FRICTION  The Coulomb and viscous friction torque [N m] at speed om [rad/s], scaled by fscale.
%   om: real[1] (passed a plain number)
%   coulomb: real[1] (passed a plain number)
%   viscous: real[1] (passed a plain number)
%   fscale: real[1] (passed a plain number)
%   returns fr: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    fr = 0;
    fr = (((coulomb * sign(om)) + (viscous * om)) * fscale);
end
